import sys
from collections import OrderedDict

def main():
    lines = sys.stdin.read().split('\n')
    c = int(lines[0].strip())
    d = OrderedDict()
    out = []
    for line in lines[1:]:
        p = line.split()
        if not p:
            continue
        if p[0] == 'put':
            k, v = int(p[1]), int(p[2])
            d[k] = v
            d.move_to_end(k)
            if len(d) > c:
                ek, _ = d.popitem(last=False)
                out.append("evict %d" % ek)
        elif p[0] == 'get':
            k = int(p[1])
            if k in d:
                d.move_to_end(k)
                out.append(str(d[k]))
            else:
                out.append("-1")
        elif p[0] == 'keys':
            if d:
                out.append(' '.join(str(k) for k in reversed(d)))
            else:
                out.append("<empty>")
    print('\n'.join(out))

main()
